def route_ticket(text):
    if not text.strip():
        return {"queue": "manual_review", "reason": "empty ticket"}
    lowered = text.lower()
    if "invoice" in lowered or "refund" in lowered:
        queue = "billing"
    elif "password" in lowered or "login" in lowered:
        queue = "account_access"
    else:
        queue = "technical_support"
    return {"queue": queue, "reason": "baseline rule"}

print(route_ticket("I need a refund for an invoice"))
